   void RefreshRight(){ImageSelector.Items.Clear();ModuleResultsGrid.ItemsSource=Array.Empty<object>();var procedure=doc.CurrentProcedure;var node=selected is null?null:procedure.Nodes.FirstOrDefault(n=>n.Id==selected);Breadcrumb.Text=GroupBreadcrumb();if(node is not null)RefreshModuleResults(node);var sources=procedure.Nodes.Where(n=>plugins.Find(n.ModuleId)is IToolImageListProvider or IToolImageOutputProvider).ToArray();refreshingImageSelector=true;NodeDocument? choice=null;try{foreach(var source in sources){if(plugins.Find(source.ModuleId) is IToolImageOutputProvider multi)foreach(var imageOutput in multi.ImageOutputs)ImageSelector.Items.Add(new ComboBoxItem{Content=source.Name+"."+imageOutput.Label,Tag=source.Id,ToolTip=imageOutput.Port});else ImageSelector.Items.Add(new ComboBoxItem{Content=source.Name+".输出图像",Tag=source.Id});}choice=sources.FirstOrDefault(n=>n.Id==activeImageSourceId)??sources.FirstOrDefault(n=>n.Id==selected)??sources.FirstOrDefault();activeImageSourceId=choice?.Id;if(choice is not null)ImageSelector.SelectedItem=ImageSelector.Items.Cast<ComboBoxItem>().FirstOrDefault(item=>(string?)item.Tag==choice.Id&&(string?)item.ToolTip==activeImageOutputPort)??ImageSelector.Items.Cast<ComboBoxItem>().FirstOrDefault(item=>(string?)item.Tag==choice.Id);activeImageOutputPort=(ImageSelector.SelectedItem as ComboBoxItem)?.ToolTip as string;}finally{refreshingImageSelector=false;}RefreshSelectedImageSourcePreview();RefreshImageSourcePanel(choice);RefreshToolDisplay(node);}
