  void RefreshSelectedImageSourcePreview(){PreviewImageName.Text="";Preview.Source=null;EmptyImage.Text="";var source=SelectedImageSource();if(source is not null){if(results.TryGetValue(source.Id,out var record)){var output=(activeImageOutputPort is null?record.Outputs.Values.FirstOrDefault(v=>DataKinds.IsImage(v.Kind)):record.Outputs.GetValueOrDefault(activeImageOutputPort))?.As<IImageData>();if(output is not null){Preview.Source=ToBitmap(output);if(source.Parameters.TryGetValue("ShowImageName",out var show)&&show.GetBoolean()&&record.Outputs.TryGetValue("CurImageName",out var name))PreviewImageName.Text=name.As<string>();}}if(Preview.Source is null&&!results.ContainsKey(source.Id)&&(!source.Parameters.TryGetValue("ImageSourceType",out var sourceMode)||sourceMode.ValueKind==JsonValueKind.Number&&sourceMode.TryGetInt32(out var mode)&&mode==1)&&source.Parameters.TryGetValue("CurrentImagePath",out var current)&&current.ValueKind==JsonValueKind.String){try{var path=current.GetString();if(!string.IsNullOrWhiteSpace(path))Preview.Source=plugins.Find(source.ModuleId) is IToolImagePreviewProvider provider?ToBitmap(provider.LoadPreview(source,path,doc.BaseDirectory,new ResourceCatalog(doc.BaseDirectory,doc.Document.Resources))):LoadBmp(path);}catch{}}}if(Preview.Source is null)EmptyImage.Text="暂无图像";}
 BitmapSource LoadThumbnail(string path){string full=System.IO.Path.IsPathRooted(path)?path:System.IO.Path.GetFullPath(path,doc.BaseDirectory);var image=new BitmapImage();image.BeginInit();image.UriSource=new Uri(full);image.DecodePixelWidth=72;image.CacheOption=BitmapCacheOption.OnLoad;image.EndInit();image.Freeze();return image;}

 
 string[] ReadStringList(NodeDocument node,string name)=>node.Parameters.TryGetValue(name,out var value)&&value.ValueKind==JsonValueKind.String?JsonSerializer.Deserialize<string[]>(value.GetString()??"[]")??[]:[];
 void SetImagePaths(NodeDocument node,IEnumerable<string> paths,string? current){var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());var list=paths.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();values["ImagePaths"]=JsonSerializer.SerializeToElement(JsonSerializer.Serialize(list));values["CurrentImagePath"]=JsonSerializer.SerializeToElement(current??"");var selectedPaths=ReadStringList(node,"SelectedPaths").Where(p=>list.Contains(p,StringComparer.OrdinalIgnoreCase)).ToArray();values["SelectedPaths"]=JsonSerializer.SerializeToElement(JsonSerializer.Serialize(selectedPaths));InvalidateSourceResults(node);doc.SetParameters(node.Id,values);}
  void InvalidateSourceResults(NodeDocument node){results.Clear();plugins.Find(node.ModuleId)?.Reset(node.Id);executionScope.ForProcedure(doc.CurrentProcedureId).RemoveNode(node.ModuleId,node.Id);}
 void AddImages(IEnumerable<string> paths){var node=SelectedImageSource();if(node is null){StatusText.Text="请先选中图像源节点";return;}var old=JsonSerializer.Deserialize<string[]>(node.Parameters["ImagePaths"].GetString()??"[]")??[];var added=paths.Where(File.Exists).ToArray();if(added.Length==0)return;SetImagePaths(node,old.Concat(added),node.Parameters["CurrentImagePath"].GetString() is {Length:>0} current?current:added[0]);}
 void AddImages(object sender,RoutedEventArgs e){var dialog=new OpenFileDialog{Title="添加图像",Filter="BMP 图像|*.bmp|所有文件|*.*",Multiselect=true};if(dialog.ShowDialog(this)==true)AddImages(dialog.FileNames);}
