  void ImageItemMouseDown(object sender,MouseButtonEventArgs e){if(sender is not FrameworkElement{DataContext:ImageListEntry entry}||SelectedImageSource() is not NodeDocument node)return;if(ImageRunMode.SelectedIndex==1&&(Keyboard.Modifiers&ModifierKeys.Control)==ModifierKeys.Control){var marked=new HashSet<string>(ReadStringList(node,"SelectedPaths"),StringComparer.OrdinalIgnoreCase);if(!marked.Add(entry.Path))marked.Remove(entry.Path);SetSourceSelection(node,marked,node.Parameters.TryGetValue("CurrentImagePath",out var old)?old.GetString():null,2);RefreshImageSourcePanel(node);e.Handled=true;return;}if(ImageRunMode.SelectedIndex==1&&(Keyboard.Modifiers&ModifierKeys.Shift)==ModifierKeys.Shift){var paths=ReadStringList(node,"ImagePaths");var current=node.Parameters.TryGetValue("CurrentImagePath",out var currentValue)?currentValue.GetString():null;int a=Array.IndexOf(paths,current??""),b=Array.IndexOf(paths,entry.Path);if(a>=0&&b>=0){int min=Math.Min(a,b),max=Math.Max(a,b);SetSourceSelection(node,paths.Skip(min).Take(max-min+1),entry.Path,2);RefreshImageSourcePanel(node);e.Handled=true;}}}
  void ImageListSelectionChanged(object sender,SelectionChangedEventArgs e){if(!IsLoaded||refreshingImageList||SelectedImageSource() is not NodeDocument node||ImageList.SelectedItem is not ImageListEntry entry)return;var allPaths=ReadStringList(node,"ImagePaths");if(!allPaths.Contains(entry.Path,StringComparer.OrdinalIgnoreCase))return;var list=ImageRunMode.SelectedIndex==1?ReadStringList(node,"SelectedPaths"):allPaths;if(ImageRunMode.SelectedIndex==1&&!list.Contains(entry.Path,StringComparer.OrdinalIgnoreCase)){list=list.Append(entry.Path).ToArray();SetSourceSelection(node,list,entry.Path,2);}if(list.Length==0)return;int index=Array.IndexOf(list,entry.Path);if(index<0)return;bool auto=AutoSwitch.IsChecked==true;int runIndex=auto?(index-1+list.Length)%list.Length:index;_=RunImageSource(node.Id,list[runIndex]);}
 void ImageRunModeChanged(object sender,SelectionChangedEventArgs e){if(!IsLoaded||refreshingImageList||SelectedImageSource() is not NodeDocument node)return;int mode=ImageRunMode.SelectedIndex==1?2:1;var selectedPaths=ReadStringList(node,"SelectedPaths");if(mode==2&&selectedPaths.Length==0&&node.Parameters.TryGetValue("CurrentImagePath",out var current)&&!string.IsNullOrWhiteSpace(current.GetString()))selectedPaths=[current.GetString()!];if(mode==1)selectedPaths=[];SetSourceSelection(node,selectedPaths,node.Parameters.TryGetValue("CurrentImagePath",out var path)?path.GetString():null,mode);}
 void SetSourceSelection(NodeDocument node,IEnumerable<string> selectedPaths,string? current,int? executeType=null){var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());var paths=selectedPaths.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();values["SelectedPaths"]=JsonSerializer.SerializeToElement(JsonSerializer.Serialize(paths));values["CurrentImagePath"]=JsonSerializer.SerializeToElement(current??"");values["ExecuteType"]=JsonSerializer.SerializeToElement(executeType??(ImageRunMode.SelectedIndex==1?2:1));InvalidateSourceResults(node);doc.SetParameters(node.Id,values);}
 void SetCurrentImage(NodeDocument node,string path){var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values["CurrentImagePath"]=JsonSerializer.SerializeToElement(path);InvalidateSourceResults(node);doc.SetParameters(node.Id,values);RefreshSelectedImageSourcePreview();}
 async Task RunImageSource(string nodeId,string imagePath){if(activeRun is not null)return;var node=doc.CurrentProcedure.Nodes.FirstOrDefault(n=>n.Id==nodeId);if(node is null)return;var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values["CurrentImagePath"]=JsonSerializer.SerializeToElement(imagePath);doc.SetParameters(nodeId,values);plugins.Find(node.ModuleId)?.Reset(nodeId);executionScope.ForProcedure(doc.CurrentProcedureId).RemoveNode(node.ModuleId,nodeId);await StartRun();}
 void AutoSwitchChanged(object sender,RoutedEventArgs e){if(!IsLoaded||refreshingImageList||SelectedImageSource() is not NodeDocument node||AutoSwitch.IsChecked is not bool enabled)return;var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values["AutoPlay"]=JsonSerializer.SerializeToElement(enabled);InvalidateSourceResults(node);doc.SetParameters(node.Id,values);}
 IImageData? InputImage(string? id)=>id is null?null:results.TryGetValue(id,out var r)?r.Outputs.Values.FirstOrDefault(v=>DataKinds.IsImage(v.Kind))?.As<IImageData>():null;
 BitmapSource? ToBitmap(IImageData g){var packed=ImagePreview.Packed(g);if(packed is null)return null;g=packed;var b=BitmapSource.Create(g.Width,g.Height,96,96,g.Format==ImagePixelFormat.Rgb24?PixelFormats.Rgb24:PixelFormats.Gray8,null,g.Pixels.ToArray(),g.Stride);b.Freeze();return b;}
 void New(){if(ConfirmPendingChanges())doc.NewSolution(false);}
 bool ConfirmPendingChanges(){if(parameterEditorOpen){StatusText.Text="请先关闭参数窗口";return false;}if(!doc.IsDirty)return true;var answer=MessageBox.Show(this,"当前方案有未保存的修改。是否先保存？","未保存的方案",MessageBoxButton.YesNoCancel,MessageBoxImage.Warning);if(answer==MessageBoxResult.Cancel)return false;if(answer==MessageBoxResult.No)return true;return Save(false);}
 void Demo(){if(!ConfirmPendingChanges())return;LoadDemo();}
 void LoadDemo(){string f=System.IO.Path.Combine(AppContext.BaseDirectory,"demo.vmx.json");if(System.IO.File.Exists(f)){doc.Load(f);}}
 void Open(){var d=new OpenFileDialog{Filter="流程方案|*.vmx.json;*.json"};if(d.ShowDialog(this)==true&&ConfirmPendingChanges())doc.Load(d.FileName);}
 bool Save(bool asNew){string? f=doc.FilePath;if(asNew||f is null){var d=new SaveFileDialog{Filter="流程方案|*.vmx.json",FileName="solution.vmx.json"};if(d.ShowDialog(this)!=true)return false;f=d.FileName;}doc.Save(f);return true;}
 void Validate(){var v=doc.Validate();StatusText.Text=v.IsValid?"流程校验通过":string.Join("；",v.Issues.Select(x=>x.Message));}

}
